        ['J\'ai un manche et une lame, mais je ne suis pas une fleur. Qui suis-je ?','Une pelle',['Un râteau','Un seau','Un arbre'],'On creuse le jardin avec moi.','Une pelle a un manche et une lame, et elle sert à creuser.','Une pelle déplace le sable bien plus vite que les mains.'],
        ['J\'ai un manche et des cordes. Qui suis-je ?','Une guitare',['Une bouteille','Une girafe','Un pull'],'On gratte mes cordes.','Une guitare a un manche et des cordes.','La plupart des guitares ont six cordes.'],
        ["Quel mois a 28 jours ?","Tous",["Février","Avril","Seulement février et avril"],"Ne réponds pas trop vite.","Chaque mois a au moins 28 jours.","Seul février en a parfois exactement 28."],
        ["Qu’est-ce qui fait le tour du monde en restant dans un coin ?","Un timbre",["Le vent","La Lune","Une mouche"],"Il est posé sur une enveloppe.","Un timbre voyage avec la lettre mais reste toujours dans le coin.","Le premier timbre du monde fut le Penny Black britannique de 1840."],
        ["Je parle sans bouche et j’entends sans oreilles. Qui suis-je ?","Un écho",["Une radio","Un chien","Une ombre"],"Tu m’entends dans la montagne.","Un écho renvoie ta voix comme si quelqu’un répondait.","Un écho naît quand le son frappe une paroi dure."],
        ["Comment un homme peut-il ne pas dormir pendant 40 jours sans être fatigué ?","Il dort la nuit",["Il boit du café","C’est un robot","Ce n’est pas possible"],"Lis bien : des jours.","Il dort tout simplement la nuit — il ne dort pas le jour.","Un humain ne tient bien que quelques jours sans dormir."],
        ["Qu’est-ce qui est léger comme une plume et que même le plus fort ne peut pas garder longtemps ?","Ton souffle",["Un ballon","Une pensée","Un flocon de neige"],"Tu le refais sans arrêt.","Le souffle ne pèse presque rien, et pourtant personne ne le retient longtemps.","Le record d’apnée dépasse 24 minutes, après avoir respiré de l’oxygène pur."],
        ["Combien de mois ont 31 jours ?","7",["5","6","8"],"Compte-les sur tes jointures.","Janvier, mars, mai, juillet, août, octobre et décembre.","Tes jointures t’aident : chaque bosse est un mois long."],
        ['Je pousse sous la terre et j\'ai des yeux. Qui suis-je ?','Une pomme de terre',['Une aiguille','Un chapeau de pirate','Un coffre au trésor'],'On peut me frire, me cuire ou m\'écraser.','La pomme de terre pousse sous terre et a des yeux.','De chaque œil peut sortir une nouvelle plante.']
